from pathlib import Path
p=Path('/home/ubuntu/labrkp-workforce/server/marketplaceApi.ts')
s=p.read_text()
needle='  app.get("/api/workers/public", async (_req, res) => { const database = await getDb(); if (!database) return res.json(memoryPublishedWorkers); return res.json(await database.collection("publishedWorkers").find({}).sort({ reviewedAt: -1 }).toArray()); });\n'
insert=needle+'  app.get("/api/admin/published-workers", async (req, res) => { if (!await requireAdmin(req)) return res.status(401).json({ error: "Admin login required" }); const database = await getDb(); if (!database) return res.json(memoryPublishedWorkers); return res.json(await database.collection("publishedWorkers").find({}).sort({ reviewedAt: -1 }).toArray()); });\n  app.delete("/api/admin/published-workers/:id", async (req, res) => { if (!await requireAdmin(req)) return res.status(401).json({ error: "Admin login required" }); const database = await getDb(); if (!database) { const index = memoryPublishedWorkers.findIndex((worker) => worker.applicationId === req.params.id || String(worker.id) === req.params.id); if (index < 0) return res.status(404).json({ error: "Published worker not found" }); const [removed] = memoryPublishedWorkers.splice(index, 1); return res.json({ removed, status: "Removed" }); } const result = await database.collection("publishedWorkers").findOneAndDelete({ $or: [{ applicationId: req.params.id }, { id: req.params.id }] }); return result ? res.json({ removed: result, status: "Removed" }) : res.status(404).json({ error: "Published worker not found" }); });\n'
